const KEY='slc-presenter-ui-prototype-v1';
const OUTPUT_KEY='slc-presenter-ui-prototype-output';
const clone=value=>JSON.parse(JSON.stringify(value));
const uid=prefix=>`${prefix}-${Date.now()}-${Math.random().toString(36).slice(2,7)}`;
const starter={songs:[{id:'prototype-song-1',title:'Great Is Your Faithfulness',alternate_title:'',author:'Worship Team',copyright:'',ccli_number:'',source_app:'UI Prototype',raw_lyrics:'[Verse 1]\n\nGreat is Your faithfulness\nMorning by morning new mercies I see\n\n[Chorus]\n\nAll I have needed Your hand has provided\nGreat is Your faithfulness, Lord, unto me',theme_id:'',background_id:'',created_at:1,updated_at:1},{id:'prototype-song-2',title:'Service Opening',alternate_title:'',author:'SLC',copyright:'',ccli_number:'',source_app:'UI Prototype',raw_lyrics:'[Welcome]\n\nWelcome to church\nWe are glad you are here\n\n[Response]\n\nThis is the day the Lord has made',theme_id:'',background_id:'',created_at:2,updated_at:2}],documents:[{id:'prototype-presentation-1',kind:'Presentation',title:'Welcome Slides',reference:'',alignment:'center',font_size:42,slides:[{name:'Welcome',title:'WELCOME',body:'TO SUPERNATURAL LIFE CHURCH',text:'WELCOME\nTO SUPERNATURAL LIFE CHURCH',background:{type:'preset',presetId:'royal-blue'}},{name:'Connect',title:'CONNECT WITH US',body:'We would love to meet you after service',text:'CONNECT WITH US\nWe would love to meet you after service',background:{type:'preset',presetId:'purple-dawn'}}]}],services:[],themes:[],media:[],translations:[{id:'prototype-kjv',code:'KJV',name:'King James Version',language:'English'}]};
const bible={Genesis:{1:['In the beginning God created the heaven and the earth.','And the earth was without form, and void; and darkness was upon the face of the deep.','And God said, Let there be light: and there was light.']},John:{3:['There was a man of the Pharisees, named Nicodemus, a ruler of the Jews:','The same came to Jesus by night, and said unto him, Rabbi, we know that thou art a teacher come from God.','Jesus answered and said unto him, Verily, verily, I say unto thee, Except a man be born again, he cannot see the kingdom of God.']},Psalms:{23:['The Lord is my shepherd; I shall not want.','He maketh me to lie down in green pastures: he leadeth me beside the still waters.','He restoreth my soul: he leadeth me in the paths of righteousness for his name’s sake.']}};
const read=()=>{try{return{...clone(starter),...JSON.parse(localStorage.getItem(KEY)||'{}')}}catch{return clone(starter)}};
const write=state=>(localStorage.setItem(KEY,JSON.stringify(state)),state);
const upsert=(list,input,prefix)=>{const stamp=Date.now(),id=input.id||uid(prefix),value={...input,id,created_at:input.created_at||stamp,updated_at:stamp},index=list.findIndex(item=>item.id===id);if(index<0)list.push(value);else list[index]=value;return value};

export function installPrototypeAdapter(){
 if(window.slcDesktop)return;window.slcPrototype=true;
 window.slcDesktop={
  listPresenterSongs:async()=>clone(read().songs),savePresenterSong:async input=>{const state=read(),saved=upsert(state.songs,input,'song');write(state);return clone(saved)},deletePresenterSong:async id=>{const state=read();state.songs=state.songs.filter(item=>item.id!==id);write(state);return true},
  listPresenterDocuments:async kind=>clone(read().documents.filter(item=>!kind||item.kind===kind)),savePresenterDocument:async input=>{const state=read(),saved=upsert(state.documents,input,'document');write(state);return clone(saved)},deletePresenterDocument:async id=>{const state=read();state.documents=state.documents.filter(item=>item.id!==id);write(state);return true},
  listPresenterServices:async()=>clone(read().services),getPresenterService:async id=>clone(read().services.find(item=>item.id===id)||null),savePresenterService:async input=>{const state=read(),saved=upsert(state.services,input,'service');write(state);return clone(saved)},
  listPresenterThemes:async()=>clone(read().themes),savePresenterTheme:async input=>{const state=read(),saved=upsert(state.themes,input,'theme');write(state);return clone(saved)},deletePresenterTheme:async id=>{const state=read();state.themes=state.themes.filter(item=>item.id!==id);write(state);return true},getPresenterThemeDefaults:async()=>read().themeDefaults||{generalThemeId:'slc-default-theme',songThemeId:'',scriptureThemeId:'',presentationThemeId:''},setPresenterThemeDefault:async(kind,id)=>{const state=read(),key=`${kind.toLowerCase()}ThemeId`;state.themeDefaults={generalThemeId:'slc-default-theme',songThemeId:'',scriptureThemeId:'',presentationThemeId:'',...state.themeDefaults,[key]:id};write(state);return clone(state.themeDefaults)},
  listBibleTranslations:async()=>clone(read().translations),listBibleBooks:async()=>Object.entries(bible).map(([book,chapters])=>({book,chapters:Object.keys(chapters).length})),listBibleVerses:async(_translation,book,chapter)=>(bible[book]?.[chapter]||[]).map((text,index)=>({verse:index+1,text})),searchBible:async(_translation,query,limit=8)=>{const terms=String(query).toLowerCase().split(/[^a-z0-9]+/).filter(term=>term.length>2),found=[];for(const[book,chapters]of Object.entries(bible))for(const[chapter,verses]of Object.entries(chapters))verses.forEach((text,index)=>{const score=terms.reduce((total,term)=>total+(text.toLowerCase().includes(term)?1:0),0);if(score)found.push({id:`${book}:${chapter}:${index+1}`,book,chapter:Number(chapter),startVerse:index+1,endVerse:index+1,reference:`${book} ${chapter}:${index+1}`,reason:text,confidence:'related',detectionType:'local_search',source:'local',timestamp:Date.now(),score})});return found.sort((a,b)=>b.score-a.score).slice(0,limit)},localAiStatus:async model=>({runtime:'unavailable',model:model||'gemma3:1b',modelReady:false,models:[],availableStorageBytes:null,error:'Local AI is available in the installed desktop app.'}),localAiSuggest:async()=>[],installLocalAiModel:async()=>{throw new Error('Install models from the desktop app.')},cancelLocalAi:async()=>true,openLocalAiInstallHelp:async()=>true,
  listPresenterMedia:async()=>clone(read().media),getSessionState:async()=>({wasUnclean:false}),listDisplays:async()=>[{id:'prototype-display',label:'Browser Output Window',primary:false}],openPresenterOutput:async outputId=>{window.open(`/presenter-output?prototype=1&output=${encodeURIComponent(outputId)}`,`slc-${outputId}`);return{ok:true,outputId,active:true,displayId:'prototype-display'}},closePresenterOutput:async()=>true,publishOutputState:payload=>{localStorage.setItem(OUTPUT_KEY,JSON.stringify(payload));window.dispatchEvent(new CustomEvent('slc-prototype-output',{detail:payload}))},onOutputState:callback=>{const emit=value=>{if(value)callback(clone(value))},custom=event=>emit(event.detail),storage=event=>{if(event.key===OUTPUT_KEY&&event.newValue)try{emit(JSON.parse(event.newValue))}catch{}};window.addEventListener('slc-prototype-output',custom);window.addEventListener('storage',storage);try{emit(JSON.parse(localStorage.getItem(OUTPUT_KEY)||'null'))}catch{}return()=>{window.removeEventListener('slc-prototype-output',custom);window.removeEventListener('storage',storage)}},onOutputStatus:()=>()=>{},onMediaLibraryChanged:()=>()=>{},onCloseRequest:()=>()=>{},respondToClose:()=>{}
 };
 window.slcHealth={get:async()=>({database:'ready',songs:read().songs.length,documents:read().documents.length,outputs:[]})};window.slcDisplays={onChanged:()=>()=>{}};
}
